func TestRequiredNullableRoundTripGetMedicationsResponse(t *testing.T) {
	requiredNullableKeys := []string{
		"defaultDirections",
		"fill",
		"form",
		"quantityUnit",
		"strength",
	}
	marshalToMap := func(t *testing.T, obj *GetMedicationsResponse) map[string]json.RawMessage {
		data, err := json.Marshal(obj)
		require.NoError(t, err, "marshaling should succeed")
		var result map[string]json.RawMessage
		require.NoError(t, json.Unmarshal(data, &result), "marshaled data should be a JSON object")
		return result
	}

	t.Run("NullPreserved", func(t *testing.T) {
		t.Parallel()
		var obj GetMedicationsResponse
		require.NoError(t, json.Unmarshal([]byte(`{"defaultDirections":null,"fill":null,"form":null,"quantityUnit":null,"strength":null}`), &obj))
		result := marshalToMap(t, &obj)
		for _, key := range requiredNullableKeys {
			value, ok := result[key]
			require.True(t, ok, "required nullable field %q received as null should be present in the output", key)
			assert.Equal(t, "null", string(value), "required nullable field %q received as null should be null in the output", key)
		}
	})

	t.Run("AbsentStaysAbsent", func(t *testing.T) {
		t.Parallel()
		var obj GetMedicationsResponse
		require.NoError(t, json.Unmarshal([]byte(`{}`), &obj))
		result := marshalToMap(t, &obj)
		for _, key := range requiredNullableKeys {
			assert.NotContains(t, result, key, "required nullable field %q absent from the input should be absent from the output", key)
		}
	})

	t.Run("FreshValueOmits", func(t *testing.T) {
		t.Parallel()
		result := marshalToMap(t, &GetMedicationsResponse{})
		for _, key := range requiredNullableKeys {
			assert.NotContains(t, result, key, "required nullable field %q should be omitted from a freshly constructed value", key)
		}
	})
}

